SELECT `id`,`team_uuid`,`project_uuid`,`session_uuid`,`member_uuid`,`intent_uuid`,`key`,`mode`,`status`,`ttl_seconds`,`expires_at`,`hard_expires_at`,`breadth_score`,`released_at`,`release_reason`,`created_at`,`updated_at`
FROM `claim`
WHERE 
    `id` = ? ;

        
-- name: FetchClaimByTeamUUIDAndKey :many
SELECT `id`,`team_uuid`,`project_uuid`,`session_uuid`,`member_uuid`,`intent_uuid`,`key`,`mode`,`status`,`ttl_seconds`,`expires_at`,`hard_expires_at`,`breadth_score`,`released_at`,`release_reason`,`created_at`,`updated_at`
FROM `claim`
WHERE 
    `key` = ? AND `team_uuid` = ? 
LIMIT ?, ?;
        
-- name: FetchClaimByProjectUUIDAndStatus :many
SELECT `id`,`team_uuid`,`project_uuid`,`session_uuid`,`member_uuid`,`intent_uuid`,`key`,`mode`,`status`,`ttl_seconds`,`expires_at`,`hard_expires_at`,`breadth_score`,`released_at`,`release_reason`,`created_at`,`updated_at`
FROM `claim`
WHERE 
    `project_uuid` = ? AND `status` = ? 
LIMIT ?, ?;
        
-- name: FetchClaimByIDForUpdate :many
SELECT `id`,`team_uuid`,`project_uuid`,`session_uuid`,`member_uuid`,`intent_uuid`,`key`,`mode`,`status`,`ttl_seconds`,`expires_at`,`hard_expires_at`,`breadth_score`,`released_at`,`release_reason`,`created_at`,`updated_at`
FROM `claim`
WHERE 
    `id` = ? 
FOR UPDATE;
        




